// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Agents create, edit and discard drafts"
// Changes: The draft tools of the agent interface: list, create, relabel and discard drafts, and edit a draft's parts.
//          Agents write only open drafts (projects, snapshots and ended drafts are refused with the reason). Every
//          edit is one store transaction and returns the draft's new revision and its fresh problems; whole-text
//          edits take an optional expectedRevision, refused only when that part changed since then.

import { SEP } from '#/lib/grammar'
import type { PartName } from '#/lib/parts'
import { writeParts } from '#/lib/parts'
import type { Relation } from '#/lib/project'
import { analyzeProject } from '#/lib/projectAnalysis'
import { z } from 'zod'
import { LABEL_MAX, type DraftEdit, type DraftRecord, type DraftSummary, type ProjectStore } from '../projects.server'
import { partValue } from './readTools.server'
import { draftRef, endedDraftError, projectOf, targetSchema, writableDraft, type TargetInput } from './targets.server'
import { READ_ONLY, ToolError, defineTool, type AgentTool } from './tools.server'
import type { ToolAnnotations } from '@modelcontextprotocol/sdk/types.js'

const WRITES_DRAFT: ToolAnnotations = { readOnlyHint: false, destructiveHint: false, idempotentHint: true, openWorldHint: false }
const CREATES: ToolAnnotations = { readOnlyHint: false, destructiveHint: false, idempotentHint: false, openWorldHint: false }
const ENDS: ToolAnnotations = { readOnlyHint: false, destructiveHint: true, idempotentHint: false, openWorldHint: false }

const PART_TEXT: Record<PartName, string> = {
  definition: 'definition',
  grammarRules: 'grammar rules',
  precTable: 'precedence table',
  reductionRules: 'reduction rules',
}

/** A draft as agents see it (no parts – read those with get_part and a draft target). */
const draftView = (d: DraftSummary | DraftRecord) => ({
  id: d.id,
  projectId: d.projectId,
  label: d.label,
  state: d.state,
  revision: d.revision,
  partRevisions: d.partRevisions,
  lastChangedBy: d.lastChangedBy,
  base: { projectRevision: d.base.projectRevision },
  createdAt: d.createdAt,
  updatedAt: d.updatedAt,
  endedAt: d.endedAt,
})

function requireLabel(label: string) {
  if (!label.trim()) throw new ToolError('The label is empty; give the draft a short label describing its purpose.')
}

const draftTarget = targetSchema.describe('The draft to change: {"kind":"draft","id":"<draft id>"} (from create_draft or list_drafts)')
const projectId = z.string().describe('Project id (from list_projects)')
const label = z.string().max(LABEL_MAX).describe(`A short label describing the draft's purpose (at most ${LABEL_MAX} characters)`)
const expectedRevision = z
  .number()
  .int()
  .optional()
  .describe(
    'The draft revision your text is based on (from your last read or edit). If the part changed since then, the edit ' +
      'is refused and the current text is returned; changes to other parts do not matter. Omit to overwrite unconditionally.',
  )

/** Applies an agent edit to an open draft and reports the new revision and fresh problems. */
function applyEdit(store: ProjectStore, target: TargetInput, edit: DraftEdit, baseRevision?: number) {
  const draft = writableDraft(store, target)
  const result = store.editDraft(draft.id, edit, { author: 'agent', baseRevision })
  switch (result.status) {
    case 'missing':
      throw new ToolError(`No draft with id "${draft.id}".`)
    case 'ended':
      throw endedDraftError(result.draft)
    case 'conflict': {
      const current = result.draft
      const part = result.parts[0]
      const data = writeParts(projectOf(store, current.projectId).data, current.parts)
      throw new ToolError(
        `The ${PART_TEXT[part]} of draft "${current.id}" were changed at revision ${current.partRevisions[part]}, after ` +
          `your expectedRevision ${baseRevision}; your edit was not applied. Merge your change into the current value ` +
          `below and retry with expectedRevision ${current.revision}.`,
        { revision: current.revision, part, partRevision: current.partRevisions[part], current: partValue(data, part) },
      )
    }
    case 'saved': {
      const saved = result.draft
      const data = writeParts(projectOf(store, saved.projectId).data, saved.parts)
      return { target: draftRef(saved), revision: saved.revision, changed: result.changed, problems: analyzeProject(data).problems }
    }
  }
}

const EDIT_RESULT =
  'Returns {target, revision (the draft\'s new revision), changed (the parts that changed; empty when the value was ' +
  'already the same), problems (definition, ll, prec – as get_problems)}. Only open drafts can be edited.'

const listDrafts = defineTool({
  name: 'list_drafts',
  description:
    "Lists a project's drafts, open ones first, then by last change: id, label, state (open, adopted, discarded), " +
    'revision, partRevisions (the draft revision that last changed each part; 1 = unchanged since the draft was ' +
    'created), lastChangedBy (agent or human), base.projectRevision (the project revision the draft was forked from) ' +
    'and times. Read a draft with {"kind":"draft","id":<id>} as the target of the read tools; resume an open draft instead of starting a new one.',
  input: { project: projectId },
  annotations: READ_ONLY,
  run: ({ project }, { store }) => {
    const p = projectOf(store, project)
    return { project: { id: p.id, name: p.name, revision: p.revision }, drafts: store.listDrafts(p.id).map(draftView) }
  },
})

const createDraft = defineTool({
  name: 'create_draft',
  description:
    "Creates a draft of a project: an editable copy of the project's four parts (definition, grammar rules, precedence " +
    'table, reduction rules) where an agent proposes changes. The project itself is never changed by agents; the ' +
    'human reviews the draft and adopts the parts they want. Export naming and simulation inputs stay with the project. ' +
    'Returns the draft and its target ({"kind":"draft","id":…}) for the read and edit tools.',
  input: { project: projectId, label },
  annotations: CREATES,
  run: ({ project, label }, { store }) => {
    requireLabel(label)
    const p = projectOf(store, project)
    const draft = store.createDraft(p.id, label, 'agent')
    if (!draft) throw new ToolError(`No project with id "${project}". Use list_projects to find project ids.`)
    return { draft: draftView(draft), target: { kind: 'draft', id: draft.id } }
  },
})

const relabelDraft = defineTool({
  name: 'relabel_draft',
  description: "Changes an open draft's label so it keeps describing what the draft has become. Does not change its revision.",
  input: { target: draftTarget, label },
  annotations: WRITES_DRAFT,
  run: ({ target, label }, { store }) => {
    requireLabel(label)
    const draft = writableDraft(store, target)
    const result = store.relabelDraft(draft.id, label)
    if (result.status === 'missing') throw new ToolError(`No draft with id "${draft.id}".`)
    if (result.status === 'ended') throw endedDraftError(result.draft)
    return { draft: draftView(result.draft) }
  },
})

const discardDraft = defineTool({
  name: 'discard_draft',
  description:
    'Discards an open draft that turned out to be a dead end. The draft ends (it becomes read-only and cannot be ' +
    'reopened); its last state is kept as a final snapshot in its history. The project is not touched. There is no ' +
    'tool to adopt a draft – only the human adopts.',
  input: { target: draftTarget },
  annotations: ENDS,
  run: ({ target }, { store }) => {
    const draft = writableDraft(store, target)
    const result = store.discardDraft(draft.id)
    if (result.status === 'missing') throw new ToolError(`No draft with id "${draft.id}".`)
    if (result.status === 'ended') throw endedDraftError(result.draft)
    return { draft: draftView(result.draft) }
  },
})

const setDefinition = defineTool({
  name: 'set_definition',
  description:
    "Replaces a draft's definition: the declared nonterminals N and terminals T (one symbol per line, optionally " +
    'followed by a note, as get_part shows them) and the start symbol S. ' +
    EDIT_RESULT,
  input: {
    target: draftTarget,
    nonterminals: z.string().max(100_000).describe('Nonterminals, one per line'),
    terminals: z.string().max(100_000).describe('Terminals, one per line'),
    start: z.string().max(1_000).describe('The start symbol'),
    expectedRevision,
  },
  annotations: WRITES_DRAFT,
  run: ({ target, nonterminals, terminals, start, expectedRevision }, { store }) =>
    applyEdit(store, target, { definition: { nonterminals, terminals, start } }, expectedRevision),
})

const ruleText = (what: string) => z.string().max(1_000_000).describe(`The whole ${what} text, one rule per line (e.g. "E -> id R")`)

const setGrammarRules = defineTool({
  name: 'set_grammar_rules',
  description:
    "Replaces a draft's grammar rules (P, one rule per line) – the LL table, sets and LL problems are computed from " +
    'them. Use get_ll_table with the draft target afterwards to check for conflicts. ' +
    EDIT_RESULT,
  input: { target: draftTarget, text: ruleText('grammar rules'), expectedRevision },
  annotations: WRITES_DRAFT,
  run: ({ target, text, expectedRevision }, { store }) => applyEdit(store, target, { grammarRules: text }, expectedRevision),
})

const setReductionRules = defineTool({
  name: 'set_reduction_rules',
  description:
    "Replaces a draft's reduction rules (one rule per line), which the precedence simulation reduces handles by. " +
    'They are separate from the grammar rules. ' +
    EDIT_RESULT,
  input: { target: draftTarget, text: ruleText('reduction rules'), expectedRevision },
  annotations: WRITES_DRAFT,
  run: ({ target, text, expectedRevision }, { store }) => applyEdit(store, target, { reductionRules: text }, expectedRevision),
})

const setPrecTerminals = defineTool({
  name: 'set_prec_terminals',
  description:
    "Sets a draft's precedence terminals (rows and columns of the precedence table, in order; $ is always added last " +
    'and must not be listed). Relations of terminals that are removed are dropped; the others are kept. ' +
    EDIT_RESULT,
  input: { target: draftTarget, terminals: z.array(z.string().max(100)).max(500).describe('Precedence terminals in table order, e.g. ["+", "*", "id"]') },
  annotations: WRITES_DRAFT,
  run: ({ target, terminals }, { store }) =>
    applyEdit(store, target, (parts) => ({ precTable: { terminals: terminals.map((t) => t.trim()), cells: parts.precTable.cells } })),
})

const setRelation = defineTool({
  name: 'set_relation',
  description:
    "Sets or clears one cell of a draft's precedence table: the relation between the terminal on top of the stack " +
    "(row) and the input terminal (column). relation is '<', '=', '>' or '' to clear the cell. Both terminals must be " +
    'precedence terminals of the draft or $. ' +
    EDIT_RESULT,
  input: {
    target: draftTarget,
    stack: z.string().describe('Row: the terminal on top of the stack (or $)'),
    input: z.string().describe('Column: the input terminal (or $)'),
    relation: z.enum(['<', '=', '>', '']).describe("'<', '=', '>' or '' to clear the cell"),
  },
  annotations: WRITES_DRAFT,
  run: ({ target, stack, input, relation }, { store }) =>
    applyEdit(store, target, (parts) => {
      const symbols = [...parts.precTable.terminals, '$']
      for (const t of [stack, input]) {
        if (!symbols.includes(t)) {
          throw new ToolError(`"${t}" is not a precedence terminal of the draft. Terminals: ${symbols.join(' ')}. Add it with set_prec_terminals first.`)
        }
      }
      const cells = { ...parts.precTable.cells }
      if (relation) cells[stack + SEP + input] = relation as Relation
      else delete cells[stack + SEP + input]
      return { precTable: { terminals: parts.precTable.terminals, cells } }
    }),
})

const clearRelations = defineTool({
  name: 'clear_relations',
  description: "Clears every relation of a draft's precedence table, keeping its terminals, to rebuild the table from scratch. " + EDIT_RESULT,
  input: { target: draftTarget },
  annotations: WRITES_DRAFT,
  run: ({ target }, { store }) => applyEdit(store, target, (parts) => ({ precTable: { terminals: parts.precTable.terminals, cells: {} } })),
})

export const DRAFT_TOOLS: readonly AgentTool[] = [
  listDrafts,
  createDraft,
  relabelDraft,
  discardDraft,
  setDefinition,
  setGrammarRules,
  setReductionRules,
  setPrecTerminals,
  setRelation,
  clearRelations,
]
